const publishingStats = `-- name: PublishingStats :one
SELECT
    count(*) FILTER (WHERE status = 'SCHEDULED' AND scheduled_at >= $2::timestamptz AND scheduled_at < $3::timestamptz)::int AS scheduled_7d,
    count(*) FILTER (WHERE status = 'IN_REVIEW')::int AS in_review,
    count(*) FILTER (WHERE status = 'PUBLISHED' AND published_at >= $4::timestamptz)::int AS published_30d,
    count(*) FILTER (WHERE status = 'FAILED')::int AS failed,
    count(*) FILTER (WHERE status = 'DRAFT')::int AS drafts
FROM publishing.content_posts
WHERE client_id = $1
`

type PublishingStatsParams struct {
	ClientID string
	NowAt    time.Time
	In7d     time.Time
	Ago30d   time.Time
}

type PublishingStatsRow struct {
	Scheduled7d  int32
	InReview     int32
	Published30d int32
	Failed       int32
	Drafts       int32
}

func (q *Queries) PublishingStats(ctx context.Context, arg PublishingStatsParams) (PublishingStatsRow, error) {
	row := q.db.QueryRow(ctx, publishingStats,
		arg.ClientID,
		arg.NowAt,
		arg.In7d,
		arg.Ago30d,
	)
	var i PublishingStatsRow
	err := row.Scan(
		&i.Scheduled7d,
		&i.InReview,
		&i.Published30d,
		&i.Failed,
		&i.Drafts,
	)
	return i, err
}

