const upsertTarget = `-- name: UpsertTarget :exec
INSERT INTO publishing.post_targets (id, post_id, social_account_id, platform, body_override, status)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (post_id, social_account_id) DO UPDATE
SET platform = EXCLUDED.platform, body_override = EXCLUDED.body_override, status = EXCLUDED.status
`

type UpsertTargetParams struct {
	ID              string
	PostID          string
	SocialAccountID string
	Platform        string
	BodyOverride    *string
	Status          PublishingPostStatus
}

func (q *Queries) UpsertTarget(ctx context.Context, arg UpsertTargetParams) error {
	_, err := q.db.Exec(ctx, upsertTarget,
		arg.ID,
		arg.PostID,
		arg.SocialAccountID,
		arg.Platform,
		arg.BodyOverride,
		arg.Status,
	)
	return err
}
